add_yaml_meta.py
#!/usr/bin/env python3
# add_yaml_meta.py — preview/apply YAML headers to /fragments/*.txt
import sys, os, argparse, hashlib, datetime, shutil
import yaml

FRAG_DIR = os.path.join(os.getcwd(), 'fragments')
BACKUP_DIR = os.path.join(os.getcwd(), 'backups')

def sha8(content: bytes) -> str:
    return hashlib.sha256(content).hexdigest()[:8]

def make_header(fragment_id, filename, origin="NODO_SEMILLA", tags=None):
    return {
        'FRAGMENT_ID': fragment_id,
        'SESSION_ID': filename,
        'TIMESTAMP': datetime.datetime.utcnow().isoformat() + 'Z',
        'ORIGEN': origin,
        'TAGS': tags or [],
        'TITLE': ''
    }

def file_has_yaml(path):
    with open(path, 'rb') as f:
        start = f.read(4)
        return start.startswith(b'---')

def prepend_yaml(path, header, apply=False):
    with open(path, 'rb') as f:
        body = f.read()
    header_yaml = '---\n' + yaml.safe_dump(header, sort_keys=False) + '---\n\n'
    new_content = header_yaml.encode('utf-8') + body
    if apply:
        os.makedirs(BACKUP_DIR, exist_ok=True)
        shutil.copy2(path, os.path.join(BACKUP_DIR, os.path.basename(path) + '.bak'))
        with open(path, 'wb') as f:
            f.write(new_content)
    return new_content

def main(args):
    files = sorted([f for f in os.listdir(FRAG_DIR) if f.lower().endswith('.txt')])
    if not files:
        print("No fragmentos en", FRAG_DIR); return
    to_process = files[:args.batch] if args.batch else files
    for fname in to_process:
        path = os.path.join(FRAG_DIR, fname)
        if file_has_yaml(path):
            print(f"[SKIP] {fname} (ya tiene YAML)")
            continue
        frag_id = os.path.splitext(fname)[0]
        with open(path, 'rb') as f:
            body = f.read()
        header = make_header(frag_id, fname, origin=args.origin, tags=args.tags)
        header['HASH'] = sha8(body)
        preview = prepend_yaml(path, header, apply=False)
        print(f"\n--- PREVIEW {fname} ---\n{preview.decode('utf-8')[:1000]}...\n")
        if args.apply:
            prepend_yaml(path, header, apply=True)
            print(f"[APPLIED] {fname} (backup -> backups/{fname}.bak)")

if __name__ == '__main__':
    p = argparse.ArgumentParser()
    p.add_argument('--apply', action='store_true', help='Aplicar cambios (si no, solo preview)')
    p.add_argument('--batch', type=int, default=10, help='Cantidad de archivos por batch (default 10)')
    p.add_argument('--origin', default='NODO_SEMILLA', help='Campo ORIGEN en YAML')
    p.add_argument('--tags', nargs='*', default=[], help='Tags iniciales')
    args = p.parse_args()
    main(args)

