#!/usr/bin/env python3
# simon_validator.py — valida encabezado YAML y HASH básico
import os, sys, yaml, hashlib, json
FRAG_DIR = os.path.join(os.getcwd(), 'fragments')

def compute_hash_body(path):
    with open(path, 'rb') as f:
        data = f.read()
    # remove YAML if present
    if data.startswith(b'---'):
        parts = data.split(b'---', 2)
        if len(parts) >= 3:
            body = parts[2]
        else:
            body = data
    else:
        body = data
    return hashlib.sha256(body).hexdigest()[:8]

def validate_fragment(path):
    with open(path, 'r', encoding='utf-8') as f:
        txt = f.read()
    if not txt.startswith('---'):
        return False, 'NO_YAML'
    parts = txt.split('---', 2)
    header_raw = parts[1]
    try:
        header = yaml.safe_load(header_raw)
    except Exception as e:
        return False, 'YAML_PARSE_ERROR:' + str(e)
    required = ['FRAGMENT_ID', 'TIMESTAMP', 'ORIGEN']
    for r in required:
        if r not in header:
            return False, f'MISSING_{r}'
    expected = header.get('HASH')
    actual = compute_hash_body(path)
    if expected and expected != actual:
        return False, f'HASH_MISMATCH (expected {expected} actual {actual})'
    return True, 'OK'

def main():
    results = {}
    for fname in sorted(os.listdir(FRAG_DIR)):
        if not fname.lower().endswith('.txt'): continue
        ok, reason = validate_fragment(os.path.join(FRAG_DIR, fname))
        results[fname] = {'ok': ok, 'reason': reason}
    print(json.dumps(results, indent=2, ensure_ascii=False))

if __name__ == '__main__':
    main()

