let fragments=[];
document.getElementById('loadBtn').onclick = () => {
  const files = Array.from(document.getElementById('folderInput').files).filter(f=>f.name.endsWith('.txt')).sort((a,b)=>a.name.localeCompare(b.name));
  fragments = files;
  const list = document.getElementById('fragmentsList');
  list.innerHTML = '';
  files.forEach((f,i)=>{
    const p = document.createElement('p');
    p.textContent = f.name;
    p.onclick = async ()=> {
      const text = await f.text();
      document.getElementById('responseArea').value = text;
    };
    list.appendChild(p);
  });
};

function downloadFile(content, filename){
  const blob = new Blob([content], {type:'text/plain'});
  const link = document.createElement('a');
  link.href = URL.createObjectURL(blob);
  link.download = filename;
  link.click();
}

document.getElementById('mergeBtn').onclick = async () => {
  let out='';
  for (const f of fragments){
    const text = await f.text();
    out += `\n----- ${f.name} -----\n${text}\n`;
  }
  downloadFile(out, `bitacora_full_${Date.now()}.txt`);
};

document.getElementById('saveResponse').onclick = ()=>{
  const txt = document.getElementById('responseArea').value;
  downloadFile(txt, `response_${Date.now()}.txt`);
};

